import { createAdminClient, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { syncOrdersJob } from '../_shared/amazon/orders.ts';

function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});}

Deno.serve(async(req:Request)=>{
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    requireInternalSecret(req);
    const body=await req.json().catch(()=>({}));
    if(!body?.job)return response({error:'Falta el job de pedidos.'},400);
    const rowsProcessed=await syncOrdersJob(createAdminClient(),body.job);
    return response({ok:true,rowsProcessed});
  }catch(error){return response({error:error instanceof Error?error.message:'No se pudieron sincronizar los pedidos Amazon.'},500);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import { spApiRequest } from './sp-api.ts';
import { loadAmazonSpApiCredentials } from './config.ts';

const INCLUDED_DATA=['PROCEEDS','EXPENSE','PROMOTION','CANCELLATION','FULFILLMENT','PACKAGES','TAX'];
const OPERATIONAL_INCLUDED_DATA=[...INCLUDED_DATA,'BUYER','RECIPIENT'];
const SAFE_LAG_MS=2*60*1000;
const EU_MARKETPLACE_IDS=new Set(['A1RKKUPIHCS9HS','A13V1IB3VIYZZH','A1PA6795UKMFR9','APJ6JRA9NG5V4','A1805IZSGTT6HS','A2NODRKZP88ZB9','A1C3SOZRARQ6R3','AMEN7PMS3EDWL','A28R8C7NBKEWEA','A1F83G8C2ARO7P']);

type Money={amount?:string|number|null;currencyCode?:string|null}|null|undefined;
function money(value:Money){const n=Number(value?.amount);return Number.isFinite(n)?n:null;}
function currency(value:Money){return value?.currencyCode?String(value.currencyCode):null;}
function minIso(value:string|undefined|null,limit:Date){if(!value)return limit.toISOString();const date=new Date(value);return (date<limit?date:limit).toISOString();}
function programs(order:any){return (Array.isArray(order?.programs)?order.programs:[]).map((value:any)=>String(value||'').trim().toUpperCase()).filter(Boolean);}

function proceedsBreakdown(proceeds:any,matcher:(type:string)=>boolean){
  const item=(proceeds?.breakdowns||[]).find((entry:any)=>matcher(String(entry?.type||'').toUpperCase()));
  return item?.subtotal||item?.value||null;
}
function taxMoney(proceeds:any){return proceedsBreakdown(proceeds,type=>type==='TAX');}
function shippingMoney(proceeds:any){return proceedsBreakdown(proceeds,type=>type.includes('SHIPPING')||type.includes('DELIVERY'));}
function discountMoney(proceeds:any){return proceedsBreakdown(proceeds,type=>type.includes('DISCOUNT')||type.includes('PROMOTION'));}

function clean(value:unknown){return String(value??'').trim();}
function merchantFulfilled(order:any){return clean(order?.fulfillment?.fulfilledBy).toUpperCase()==='MERCHANT';}
function operationalAddress(order:any){
  const address=order?.recipient?.deliveryAddress||{};
  const extended=address?.extendedFields||{};
  return {
    name:clean(address.name||order?.buyer?.buyerName)||null,
    company_name:clean(address.companyName||order?.buyer?.buyerCompanyName)||null,
    address_line_1:clean(address.addressLine1)||null,
    house_number:clean(extended.streetNumber)||null,
    address_line_2:[address.addressLine2,address.addressLine3].map(clean).filter(Boolean).join(' · ')||null,
    postal_code:clean(address.postalCode)||null,
    city:clean(address.city||address.municipality)||null,
    state_province_code:clean(address.stateOrRegion||address.districtOrCounty)||null,
    country_code:clean(address.countryCode).toUpperCase()||null,
    email:clean(order?.buyer?.buyerEmail)||null,
    phone_number:clean(address.phone)||null,
  };
}
function mergeOperationalAddress(current:any,fresh:any){
  const original=current?.raw_payload?.shipping_address||{},saved=current?.shipping_address||{};
  const result:any={};
  for(const [key,value] of Object.entries(original))if(clean(value))result[key]=value;
  for(const [key,value] of Object.entries(saved))if(clean(value))result[key]=value;
  if(current?.raw_payload?._zenvia_local_shipping_updated_at)return {...result,...saved};
  for(const [key,value] of Object.entries(fresh||{}))if(clean(value))result[key]=value;
  return result;
}
function operationalItems(order:any){
  return (Array.isArray(order?.orderItems)?order.orderItems:[]).map((item:any)=>{
    const product=item?.product||{},proceeds=item?.proceeds||null;
    const itemAmount=proceedsBreakdown(proceeds,type=>type==='ITEM')||proceeds?.proceedsTotal||null;
    const quantity=Math.max(1,Number(item?.quantityOrdered)||1);
    const total=money(itemAmount);
    return {
      item_id:clean(item?.orderItemId)||null,
      sku:clean(product?.sellerSku)||null,
      product_id:clean(product?.asin)||null,
      name:clean(product?.title||product?.productName||product?.name||product?.sellerSku||product?.asin)||'Producto Amazon',
      quantity,
      unit_price:total==null?null:{value:Number((total/quantity).toFixed(2)),currency:currency(itemAmount)||'EUR'},
      total_price:total==null?null:{value:total,currency:currency(itemAmount)||'EUR'},
    };
  });
}
function mergeOperationalItems(existing:any[],fresh:any[]){
  const previous=Array.isArray(existing)?existing:[];
  return fresh.map(item=>{
    const match=previous.find(old=>clean(old?.item_id)===clean(item.item_id))
      ||previous.find(old=>clean(old?.sku)&&clean(old?.sku)===clean(item.sku))
      ||previous.find(old=>clean(old?.product_id)&&clean(old?.product_id)===clean(item.product_id));
    return match?{...match,...item,image_url:match.image_url||null,measurement:match.measurement||null}:item;
  });
}
async function amazonIntegrationAccount(admin:any,job:any){
  const {data,error}=await admin.from('integration_accounts')
    .select('id,config,display_name')
    .eq('owner_id',job.owner_id)
    .eq('provider','amazon')
    .eq('linked_resource_id',job.amazon_account_id)
    .eq('enabled',true)
    .neq('status','disabled')
    .maybeSingle();
  if(error)throw error;
  return data||null;
}
async function amazonIntegrationAccountId(admin:any,job:any){
  const account=await amazonIntegrationAccount(admin,job);
  return account?.id?String(account.id):null;
}
async function markOperationalReadiness(admin:any,job:any,status:'ready'|'pii_permission_missing',message=''){
  const account=await amazonIntegrationAccount(admin,job);
  if(!account?.id)return;
  const config=(account.config&&typeof account.config==='object'&&!Array.isArray(account.config))?account.config:{};
  const current=(config as any).operationalOrdersDirect||{};
  if(current?.status===status&&String(current?.message||'')===message)return;
  const next={
    ...config,
    operationalOrdersDirect:{
      status,
      checkedAt:new Date().toISOString(),
      ...(message?{message}:{}),
    },
  };
  const {error}=await admin.from('integration_accounts').update({config:next}).eq('id',account.id).eq('owner_id',job.owner_id);
  if(error)throw error;
}
async function fallbackWeightKg(admin:any,ownerId:string){
  const {data,error}=await admin.from('app_settings').select('config').eq('owner_id',ownerId).maybeSingle();
  if(error)throw error;
  const value=Number(data?.config?.shipping?.fallbackWeightKg);
  return Number.isFinite(value)&&value>0?value:1;
}
// Compare PostgreSQL JSONB values independently of object-key order. Observation
// timestamps are not business changes; unchanged rows keep their last write time.
function canonical(value:any):string{
  if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';
  if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+canonical(value[key])).join(',')+'}';
  return JSON.stringify(value??null);
}
function sameField(key:string,a:any,b:any){
  if(a==null&&b==null)return true;
  if((key.endsWith('_at')||key==='order_created_at'||key==='order_updated_at')&&a&&b){
    const left=Date.parse(a),right=Date.parse(b);if(Number.isFinite(left)&&Number.isFinite(right))return left===right;
  }
  if(key==='items'){
    const normalized=(items:any)=>Array.isArray(items)?items.map(item=>Object.fromEntries(Object.entries(item).filter(([k,v])=>!(['image_url','measurement'].includes(k)&&v==null)))):items;
    return canonical(normalized(a))===canonical(normalized(b));
  }
  return canonical(a)===canonical(b);
}
function preservePersistedFields(current:any,patch:any){
  const pending=['pending','pendingavailability','invoiceunconfirmed','unshipped','partiallyshipped'].includes(clean(patch.source_status).toLowerCase().replaceAll('_',''));
  // Same monotonic-state rules as fulfillment_amazon_status_freshness: stale
  // reads must not generate writes that the SQL trigger would immediately undo.
  if(current&&(current.fulfilled_at&&pending||current.order_updated_at&&patch.order_updated_at&&Date.parse(patch.order_updated_at)<Date.parse(current.order_updated_at))){
    patch.source_status=current.source_status;patch.order_updated_at=current.order_updated_at;
    if('fulfilled_at' in patch)patch.fulfilled_at=current.fulfilled_at;
  }
  const cancellations=current?._amazonConfirmedCancellations||[];
  if(cancellations.some((op:any)=>op.kind==='order'))patch.source_status=current.source_status;
  const matchesLabel=(row:any,op:any)=>op.kind==='label'&&(op.details?.shipmentRef===String(row.shipping_remote_id??row.sendcloud_parcel_id??row.tracking_number??'')||clean(op.details?.trackingNumber)&&op.details.trackingNumber===row.tracking_number);
  if(cancellations.some((op:any)=>matchesLabel({...current,...patch},op))){
    const replacement=current.label_created_at&&!cancellations.some((op:any)=>matchesLabel(current,op));
    for(const key of ['tracking_number','tracking_status_code','tracking_status_message','tracking_updated_at','fulfilled_at']){
      if(replacement)delete patch[key];else patch[key]=null;
    }
  }
  // The label provider owns the dispatched carrier and service. Amazon may
  // echo an old/default carrier even when the locally purchased label differs.
  // Preserve that identity in both the full import and standalone reconciliation.
  if(current&&(current.sendcloud_parcel_id!=null||current.sendcloud_shipment_id||
    ((current.shipping_provider||(current.shipping_cost_amount!=null&&current.shipping_cost_source&&current.shipping_cost_source!=='tariff_estimate'))&&
      (current.shipping_remote_id||current.label_created_at)))){
    for(const key of ['carrier_code','carrier_name','shipping_service_name','shipping_option_code','contract_id','shipping_provider','shipping_remote_id','sendcloud_parcel_id','sendcloud_shipment_id','shipping_integration_account_id','shipping_label_url','label_created_at','tracking_number','tracking_url','tracking_status_code','tracking_status_message','tracking_updated_at','shipping_cost_amount','shipping_cost_currency','shipping_cost_source','shipping_cost_net_amount','shipping_cost_tax_amount','shipping_cost_recorded_at','fulfilled_at'])delete patch[key];
  }
  if(!current?.pii_purged_at)return;
  // Match the SQL retention guard before comparing, so redacted rows do not
  // receive the same doomed-to-be-redacted PII on every page.
  for(const key of ['customer_name','customer_email','customer_phone','shipping_address','raw_payload','tracking_number','tracking_status_message'])delete patch[key];
  if(patch.items)patch.items=patch.items.map((item:any)=>Object.fromEntries(['item_id','sku','product_id','quantity','unit_price','total_price'].filter(key=>item[key]!=null).map(key=>[key,item[key]])));
}
function changedBusiness(current:any,patch:any){
  return Object.entries(patch).some(([key,value])=>key!=='last_synced_at'&&key!=='tracking_updated_at'&&!sameField(key,current?.[key],value));
}
function operationalStatePatch(order:any,current:any={}){
  const status=clean(order?.fulfillment?.fulfillmentStatus);
  if(!status)return {};
  const shipment=(Array.isArray(order.packages)?order.packages:[]).find((p:any)=>clean(p?.trackingNumber));
  const patch:any={source_status:status,order_updated_at:order.lastUpdatedTime||current.order_updated_at||null};
  if(shipment){
    patch.tracking_number=clean(shipment.trackingNumber);
    const carrier=typeof shipment.carrier==='string'?shipment.carrier:shipment.carrier?.name||shipment.carrier?.carrierCode;
    if(carrier){patch.marketplace_carrier=clean(carrier);patch.carrier_name=clean(carrier);patch.carrier_code=clean(carrier).toLowerCase()}
    if(shipment.shippingService)patch.shipping_service_name=typeof shipment.shippingService==='string'?shipment.shippingService:shipment.shippingService.name||null;
    patch.tracking_status_code=clean(shipment.packageStatus?.status)||status;
    patch.tracking_status_message=clean(shipment.packageStatus?.detailedStatus)||status;
    if(Object.entries(patch).some(([key,value])=>key.startsWith('tracking_')&&!sameField(key,current[key],value)))patch.tracking_updated_at=new Date().toISOString();
  }
  if(status.toUpperCase()==='SHIPPED')patch.fulfilled_at=shipment?.shipTime||order.lastUpdatedTime||current.fulfilled_at||new Date().toISOString();
  return patch;
}
async function attachConfirmedCancellations(admin:any,rows:any[],ownerId:string){
  if(!rows.length)return;
  const {data,error}=await admin.from('order_cancellation_operations').select('order_id,kind,details').eq('owner_id',ownerId).eq('status','confirmed').in('order_id',rows.map(row=>row.id));
  if(error)throw error;
  for(const row of rows)row._amazonConfirmedCancellations=(data||[]).filter((op:any)=>op.order_id===row.id);
}
export async function reconcileOperationalAmazonStates(admin:any,orders:any[],ownerId:string){
  const valid=orders.filter(order=>order?.orderId&&clean(order?.fulfillment?.fulfillmentStatus));
  if(!valid.length)return;
  const {data:existing,error:readError}=await admin.from('fulfillment_orders').select('*').eq('owner_id',ownerId).eq('source_channel','amazon').in('order_number',valid.map(order=>String(order.orderId)));
  if(readError)throw readError;
  await attachConfirmedCancellations(admin,existing||[],ownerId);
  for(const order of valid)for(const current of (existing||[]).filter((row:any)=>row.order_number===String(order.orderId))){
    const patch=operationalStatePatch(order,current);
    preservePersistedFields(current,patch);
    if(!changedBusiness(current,patch))continue;
    const {error}=await admin.from('fulfillment_orders').update({...patch,last_synced_at:new Date().toISOString()}).eq('owner_id',ownerId).eq('id',current.id);
    if(error)throw error;
  }
}
async function upsertOperationalAmazonOrders(admin:any,orders:any[],job:any){
  // Merchant states are merged into their single business-data write below.
  await reconcileOperationalAmazonStates(admin,orders.filter(order=>!merchantFulfilled(order)),job.owner_id);
  const candidates=orders.filter(order=>order?.orderId&&merchantFulfilled(order));
  if(!candidates.length)return 0;
  const sourceAccount=await amazonIntegrationAccount(admin,job);
  const sourceIntegrationAccountId=sourceAccount?.id?String(sourceAccount.id):null;
  if(!sourceIntegrationAccountId){await reconcileOperationalAmazonStates(admin,candidates,job.owner_id);return 0;}
  const orderIds=candidates.map(order=>String(order.orderId));
  const {data:existing,error:existingError}=await admin.from('fulfillment_orders')
    .select('*')
    .eq('owner_id',job.owner_id)
    .eq('source_channel','amazon')
    .in('order_number',orderIds);
  if(existingError)throw existingError;
  await attachConfirmedCancellations(admin,existing||[],job.owner_id);
  const existingByOrder=new Map((existing||[]).map((row:any)=>[String(row.order_number||row.order_id||''),row]));
  const fallbackWeight=await fallbackWeightKg(admin,job.owner_id);
  let synced=0;
  for(const order of candidates){
    const orderId=String(order.orderId),current=existingByOrder.get(orderId)||null;
    const address=mergeOperationalAddress(current,operationalAddress(order)),freshItems=operationalItems(order);
    const grandTotal=order?.proceeds?.grandTotal||null;
    const rawPayload={
      ...(current?.raw_payload&&typeof current.raw_payload==='object'?current.raw_payload:{}),
      amazon:{
        marketplaceId:clean(order?.salesChannel?.marketplaceId||job.marketplace_id),
        programs:programs(order),
        deliveryPreference:order?.recipient?.deliveryPreference||null,
      },
      shipping_details:{
        ...(current?.raw_payload?.shipping_details||{}),
        measurement:{
          ...(current?.raw_payload?.shipping_details?.measurement||{}),
          weight:current?.raw_payload?.shipping_details?.measurement?.weight||{value:fallbackWeight,unit:'kg'},
        },
      },
    };
    const patch:any={
      order_id:orderId,order_number:orderId,
      source_integration_account_id:sourceIntegrationAccountId,
      integration_name:clean(sourceAccount?.display_name)||current?.integration_name||'Amazon',integration_type:'amazon-direct',source_channel:'amazon',
      source_status:clean(order?.fulfillment?.fulfillmentStatus)||null,
      order_created_at:order?.createdTime||null,order_updated_at:order?.lastUpdatedTime||null,
      customer_name:address.name||clean(order?.buyer?.buyerName)||current?.customer_name||null,
      customer_email:address.email||current?.customer_email||null,customer_phone:address.phone_number||current?.customer_phone||null,
      shipping_address:address,
      items:freshItems.length?mergeOperationalItems(current?.items||[],freshItems):(current?.items||[]),
      total_amount:grandTotal?money(grandTotal):(current?.total_amount??null),currency:currency(grandTotal)||current?.currency||null,
      raw_payload:rawPayload,...operationalStatePatch(order,current||{}),last_synced_at:new Date().toISOString(),
    };
    if(current?.id){
      preservePersistedFields(current,patch);
      if(!changedBusiness(current,patch)){synced+=1;continue;}
      const {error:updateError}=await admin.from('fulfillment_orders').update(patch).eq('id',current.id).eq('owner_id',job.owner_id);
      if(updateError)throw updateError;
    }else{
      const syntheticId=`amazon:${job.amazon_account_id}:${orderId}`;
      const {error:insertError}=await admin.from('fulfillment_orders').insert({
        owner_id:job.owner_id,sendcloud_id:syntheticId,integration_id:0,billing_address:{},...patch,
      });
      if(insertError){
        if(String(insertError?.code||'')==='23505'){
          const {error:updateError}=await admin.from('fulfillment_orders').update(patch).eq('owner_id',job.owner_id).eq('sendcloud_id',syntheticId);
          if(updateError)throw updateError;
        }else throw insertError;
      }
    }
    synced+=1;
  }
  // Legacy carrier imports may leave additional copies of the same order.
  // Re-read after our merged write: the canonical copy is now a no-op, while
  // differing legacy copies still receive the authoritative status once.
  await reconcileOperationalAmazonStates(admin,candidates,job.owner_id);
  return synced;
}

export function normalizeAmazonOrder(order:any,job:any){
  const marketplaceId=String(order?.salesChannel?.marketplaceId||job.marketplace_id||'');
  const grandTotal=order?.proceeds?.grandTotal||null;
  const tax=taxMoney(order?.proceeds);
  const shipping=shippingMoney(order?.proceeds);
  const discount=discountMoney(order?.proceeds);
  const orderPrograms=programs(order);
  return {
    owner_id:job.owner_id,
    amazon_account_id:job.amazon_account_id,
    amazon_order_id:String(order?.orderId||''),
    marketplace_id:marketplaceId,
    purchase_date:order?.createdTime||null,
    last_update_date:order?.lastUpdatedTime||null,
    order_status:order?.fulfillment?.fulfillmentStatus||null,
    fulfillment_channel:order?.fulfillment?.fulfilledBy||null,
    sales_channel:order?.salesChannel?.channelName||null,
    currency_code:currency(grandTotal)||currency(tax)||null,
    gross_sales:money(grandTotal),
    vat_amount:money(tax),
    shipping_amount:money(shipping),
    promotion_discount:money(discount),
    order_total:money(grandTotal),
    programs:orderPrograms,
    is_business_order:orderPrograms.includes('AMAZON_BUSINESS'),
    synced_at:new Date().toISOString(),
    updated_at:new Date().toISOString(),
  };
}

export function normalizeAmazonOrderItems(order:any,job:any){
  const marketplaceId=String(order?.salesChannel?.marketplaceId||job.marketplace_id||'');
  return (order?.orderItems||[]).filter((item:any)=>item?.orderItemId).map((item:any)=>{
    const proceeds=item?.proceeds||null;
    const itemAmount=proceedsBreakdown(proceeds,type=>type==='ITEM')||proceeds?.proceedsTotal||null;
    const tax=taxMoney(proceeds);
    const shipping=shippingMoney(proceeds);
    const discount=discountMoney(proceeds);
    const unitPrice=item?.product?.price?.unitPrice||null;
    const quantity=Number(item?.quantityOrdered)||0;
    const derivedPrice=money(itemAmount)??(money(unitPrice)!=null?money(unitPrice)!*quantity:null);
    return {
      owner_id:job.owner_id,
      amazon_account_id:job.amazon_account_id,
      amazon_order_id:String(order?.orderId||''),
      marketplace_id:marketplaceId,
      order_item_id:String(item.orderItemId),
      asin:item?.product?.asin?String(item.product.asin):null,
      seller_sku:item?.product?.sellerSku?String(item.product.sellerSku):null,
      quantity_ordered:quantity,
      quantity_shipped:Number(item?.fulfillment?.quantityFulfilled)||0,
      item_price:derivedPrice,
      item_tax:money(tax),
      shipping_price:money(shipping),
      shipping_tax:null,
      promotion_discount:money(discount),
      currency_code:currency(itemAmount)||currency(unitPrice)||currency(tax)||null,
      synced_at:new Date().toISOString(),
      updated_at:new Date().toISOString(),
    };
  });
}

async function upsertPage(admin:any,orders:any[],job:any){
  const orderRows=orders.filter(order=>order?.orderId).map(order=>normalizeAmazonOrder(order,job));
  const itemRows=orders.flatMap(order=>normalizeAmazonOrderItems(order,job));
  if(orderRows.length){
    const {error}=await admin.from('amazon_orders').upsert(orderRows,{onConflict:'owner_id,amazon_account_id,marketplace_id,amazon_order_id'});
    if(error)throw error;
  }
  if(itemRows.length){
    const {error}=await admin.from('amazon_order_items').upsert(itemRows,{onConflict:'owner_id,amazon_account_id,marketplace_id,amazon_order_id,order_item_id'});
    if(error)throw error;
  }
  const operational=await upsertOperationalAmazonOrders(admin,orders,job);
  return orderRows.length+itemRows.length+operational;
}

export async function syncOrdersJob(admin:any,job:any,deadline=Date.now()+300_000){
  const grouped=Array.isArray(job?.payload?.marketplace_ids);
  const marketplaceIds:string[]=grouped?[...new Set<string>(job.payload.marketplace_ids)].sort():[job?.marketplace_id];
  if(grouped&&(job.payload.region!=='EU'||job.scope_key!=='region:EU'||job.marketplace_id||!marketplaceIds.length||marketplaceIds.some(id=>!EU_MARKETPLACE_IDS.has(id))))throw new Error('Unsupported Amazon region, scope or marketplace.');
  if(!marketplaceIds[0]||!job?.window_from)throw new Error('Job de pedidos incompleto.');
  const mode=String(job?.payload?.mode||'hourly');
  const safeBefore=new Date(Date.now()-SAFE_LAG_MS);
  const before=minIso(job.window_to,safeBefore);
  if(new Date(job.window_from)>=new Date(before)){job.orders_completed_before=before;return 0;}
  const baseQuery:any={
    marketplaceIds,
    maxResultsPerPage:100,
    includedData:OPERATIONAL_INCLUDED_DATA,
  };
  if(mode==='initial'){
    baseQuery.createdAfter=job.window_from;
    baseQuery.createdBefore=before;
  }else{
    baseQuery.lastUpdatedAfter=job.window_from;
    baseQuery.lastUpdatedBefore=before;
  }
  const credentials=await loadAmazonSpApiCredentials(admin,{amazonAccountId:job.amazon_account_id,ownerId:job.owner_id});
  let paginationToken:string|undefined;
  let processed=0;
  do{
    // Leave room for the client's bounded retries and lease/failure bookkeeping.
    // No cursor is discarded on success: budget exhaustion retries the whole window.
    if(grouped&&Date.now()>=deadline-150_000)throw new Error('Amazon Orders runtime budget exhausted before page completion.');
    const query={...baseQuery,...(paginationToken?{paginationToken}:{})};
    let data:any;
    try{
      data=await spApiRequest('/orders/2026-01-01/orders',{query},credentials);
      await markOperationalReadiness(admin,job,'ready');
    }catch(error){
      const message=error instanceof Error?error.message:String(error);
      if(!/Amazon SP-API \(403\)/.test(message))throw error;
      await markOperationalReadiness(
        admin,
        job,
        'pii_permission_missing',
        'Amazon no ha autorizado BUYER/RECIPIENT para esta aplicación. El análisis sigue sincronizando, pero los pedidos operativos directos necesitan acceso PII de destinatario.',
      );
      data=await spApiRequest('/orders/2026-01-01/orders',{query:{...query,includedData:INCLUDED_DATA}},credentials);
    }
    const orders=Array.isArray(data?.orders)?data.orders:[];
    // Validate the entire page before any write; never attribute a grouped
    // response with absent marketplace identity to the first requested market.
    if(orders.some((order:any)=>grouped?(!order?.salesChannel?.marketplaceId||!marketplaceIds.includes(order.salesChannel.marketplaceId)):(order?.salesChannel?.marketplaceId&&!marketplaceIds.includes(order.salesChannel.marketplaceId))))throw new Error('Amazon response marketplace outside requested scope.');
    if(grouped){
      for(const marketplaceId of marketplaceIds){
        const scoped=orders.filter((order:any)=>order.salesChannel.marketplaceId===marketplaceId);
        if(scoped.length)processed+=await upsertPage(admin,scoped,{...job,marketplace_id:marketplaceId});
      }
    }else processed+=await upsertPage(admin,orders,job);
    paginationToken=data?.pagination?.nextToken||undefined;
  }while(paginationToken);
  job.orders_completed_before=before;
  return processed;
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}
